28	// ProtoFromTraces translates internal trace data into the Jaeger Proto for GRPC.
29	// Returns slice of translated Jaeger batches and error if translation failed.
30	func ProtoFromTraces(td ptrace.Traces) []*model.Batch {
31		resourceSpans := td.ResourceSpans()
32	
33		if resourceSpans.Len() == 0 {
34			return nil
35		}
36	
37		batches := make([]*model.Batch, 0, resourceSpans.Len())
38		for i := 0; i < resourceSpans.Len(); i++ {
39			rs := resourceSpans.At(i)
40			batch := resourceSpansToJaegerProto(rs)
41			if batch != nil {
42				batches = append(batches, batch)
43			}
44		}
45	
46		return batches
47	}
48	
49	func resourceSpansToJaegerProto(rs ptrace.ResourceSpans) *model.Batch {
50		resource := rs.Resource()
51		ilss := rs.ScopeSpans()
52	
53		if resource.Attributes().Len() == 0 && ilss.Len() == 0 {
54			return nil
55		}
56	
57		batch := &model.Batch{
58			Process: resourceToJaegerProtoProcess(resource),
59		}
60	
61		if ilss.Len() == 0 {
62			return batch
63		}
64	
65		// Approximate the number of the spans as the number of the spans in the first
66		// instrumentation library info.
67		jSpans := make([]*model.Span, 0, ilss.At(0).Spans().Len())
68	
69		for i := 0; i < ilss.Len(); i++ {
70			ils := ilss.At(i)
71			spans := ils.Spans()
72			for j := 0; j < spans.Len(); j++ {
73				span := spans.At(j)
74				jSpan := spanToJaegerProto(span, ils.Scope())
75				if jSpan != nil {
76					jSpans = append(jSpans, jSpan)
77				}
78			}
79		}
80	
81		batch.Spans = jSpans
82	
83		return batch
84	}
85	
86	func resourceToJaegerProtoProcess(resource pcommon.Resource) *model.Process {
87		process := &model.Process{}
88		attrs := resource.Attributes()
89		if attrs.Len() == 0 {
90			process.ServiceName = noServiceName
91			return process
92		}
93		attrsCount := attrs.Len()
94		if serviceName, ok := attrs.Get(otelsemconv.ServiceNameKey); ok {
95			process.ServiceName = serviceName.Str()
96			attrsCount--
97		}
98		if attrsCount == 0 {
99			return process
100		}
101	
102		tags := make([]model.KeyValue, 0, attrsCount)
103		process.Tags = appendTagsFromResourceAttributes(tags, attrs)
104		return process
105	}
106	
107	func appendTagsFromResourceAttributes(dest []model.KeyValue, attrs pcommon.Map) []model.KeyValue {
108		if attrs.Len() == 0 {
109			return dest
110		}
111	
112		for key, attr := range attrs.All() {
113			if key == otelsemconv.ServiceNameKey {
114				continue
115			}
116			dest = append(dest, attributeToJaegerProtoTag(key, attr))
117		}
118		return dest
119	}
120	
121	func appendTagsFromAttributes(dest []model.KeyValue, attrs pcommon.Map) []model.KeyValue {
122		if attrs.Len() == 0 {
123			return dest
124		}
125		for key, attr := range attrs.All() {
126			dest = append(dest, attributeToJaegerProtoTag(key, attr))
127		}
128		return dest
129	}
130	
131	func attributeToJaegerProtoTag(key string, attr pcommon.Value) model.KeyValue {
132		tag := model.KeyValue{Key: key}
133		switch attr.Type() {
134		case pcommon.ValueTypeInt:
135			tag.VType = model.ValueType_INT64
136			tag.VInt64 = attr.Int()
137		case pcommon.ValueTypeBool:
138			tag.VType = model.ValueType_BOOL
139			tag.VBool = attr.Bool()
140		case pcommon.ValueTypeDouble:
141			tag.VType = model.ValueType_FLOAT64
142			tag.VFloat64 = attr.Double()
143		case pcommon.ValueTypeBytes:
144			tag.VType = model.ValueType_BINARY
145			tag.VBinary = attr.Bytes().AsRaw()
146		case pcommon.ValueTypeMap, pcommon.ValueTypeSlice:
147			tag.VType = model.ValueType_STRING
148			tag.VStr = attr.AsString()
149		default:
150			tag.VType = model.ValueType_STRING
151			tag.VStr = attr.Str()
152		}
153		return tag
154	}
