173	func getJaegerProtoSpanTags(span ptrace.Span, scope pcommon.InstrumentationScope) []model.KeyValue {
174		var spanKindTag, statusCodeTag, errorTag, statusMsgTag model.KeyValue
175		var spanKindTagFound, statusCodeTagFound, errorTagFound, statusMsgTagFound bool
176	
177		libraryTags, libraryTagsFound := getTagsFromInstrumentationLibrary(scope)
178	
179		tagsCount := span.Attributes().Len() + len(libraryTags)
180	
181		spanKindTag, spanKindTagFound = getTagFromSpanKind(span.Kind())
182		if spanKindTagFound {
183			tagsCount++
184		}
185		status := span.Status()
186		statusCodeTag, statusCodeTagFound = getTagFromStatusCode(status.Code())
187		if statusCodeTagFound {
188			tagsCount++
189		}
190	
191		errorTag, errorTagFound = getErrorTagFromStatusCode(status.Code())
192		if errorTagFound {
193			tagsCount++
194		}
195	
196		statusMsgTag, statusMsgTagFound = getTagFromStatusMsg(status.Message())
197		if statusMsgTagFound {
198			tagsCount++
199		}
200	
201		traceStateTags, traceStateTagsFound := getTagsFromTraceState(span.TraceState().AsRaw())
202		if traceStateTagsFound {
203			tagsCount += len(traceStateTags)
204		}
205	
206		if tagsCount == 0 {
207			return nil
208		}
209	
210		tags := make([]model.KeyValue, 0, tagsCount)
211		if libraryTagsFound {
212			tags = append(tags, libraryTags...)
213		}
214		tags = appendTagsFromAttributes(tags, span.Attributes())
215		if spanKindTagFound {
216			tags = append(tags, spanKindTag)
217		}
218		if statusCodeTagFound {
219			tags = append(tags, statusCodeTag)
220		}
221		if errorTagFound {
222			tags = append(tags, errorTag)
223		}
224		if statusMsgTagFound {
225			tags = append(tags, statusMsgTag)
226		}
227		if traceStateTagsFound {
228			tags = append(tags, traceStateTags...)
229		}
230		return tags
231	}
