5	package dbmodel
6	
7	import (
8		"fmt"
9		"strings"
10	
11		"github.com/jaegertracing/jaeger-idl/model/v1"
12	)
13	
14	const (
15		// warningStringPrefix is a magic string prefix for tag names to store span warnings.
16		warningStringPrefix = "$$span.warning."
17	)
18	
19	var (
20		dbToDomainRefMap = map[string]model.SpanRefType{
21			childOf:     model.SpanRefType_CHILD_OF,
22			followsFrom: model.SpanRefType_FOLLOWS_FROM,
23		}
24	
25		domainToDBRefMap = map[model.SpanRefType]string{
26			model.SpanRefType_CHILD_OF:     childOf,
27			model.SpanRefType_FOLLOWS_FROM: followsFrom,
28		}
29	
30		domainToDBValueTypeMap = map[model.ValueType]string{
31			model.StringType:  stringType,
32			model.BoolType:    boolType,
33			model.Int64Type:   int64Type,
34			model.Float64Type: float64Type,
35			model.BinaryType:  binaryType,
36		}
37	)
38	
39	// FromDomain converts a domain model.Span to a database Span
40	func FromDomain(span *model.Span) *Span {
41		return converter{}.fromDomain(span)
42	}
43	
44	// ToDomain converts a database Span to a domain model.Span
45	func ToDomain(dbSpan *Span) (*model.Span, error) {
46		return converter{}.toDomain(dbSpan)
47	}
48	
49	// converter converts Spans between domain and database representations.
50	// It primarily exists to namespace the conversion functions.
51	type converter struct{}
52	
53	func (c converter) fromDomain(span *model.Span) *Span {
54		tags := c.toDBTags(span.Tags)
55		warnings := c.toDBWarnings(span.Warnings)
56		logs := c.toDBLogs(span.Logs)
57		refs := c.toDBRefs(span.References)
58		udtProcess := c.toDBProcess(span.Process)
59		spanHash, _ := model.HashCode(span)
60	
61		tags = append(tags, warnings...)
62	
63		//nolint:gosec // G115
64		return &Span{
65			TraceID:       TraceIDFromDomain(span.TraceID),
66			SpanID:        int64(span.SpanID),
67			OperationName: span.OperationName,
68			Flags:         int32(span.Flags),
69			StartTime:     int64(model.TimeAsEpochMicroseconds(span.StartTime)),
70			Duration:      int64(model.DurationAsMicroseconds(span.Duration)),
71			Tags:          tags,
72			Logs:          logs,
73			Refs:          refs,
74			Process:       udtProcess,
75			ServiceName:   span.Process.ServiceName,
76			SpanHash:      int64(spanHash),
77		}
78	}
79	
80	func (c converter) toDomain(dbSpan *Span) (*model.Span, error) {
81		tags, err := c.fromDBTags(dbSpan.Tags)
82		if err != nil {
83			return nil, err
84		}
85		warnings, err := c.fromDBWarnings(dbSpan.Tags)
86		if err != nil {
87			return nil, err
88		}
89		logs, err := c.fromDBLogs(dbSpan.Logs)
90		if err != nil {
91			return nil, err
92		}
93		refs, err := c.fromDBRefs(dbSpan.Refs)
94		if err != nil {
95			return nil, err
96		}
97		process, err := c.fromDBProcess(dbSpan.Process)
98		if err != nil {
99			return nil, err
100		}
101		traceID := dbSpan.TraceID.ToDomain()
102		span := &model.Span{
103			TraceID: traceID,
104			//nolint:gosec // G115
105			SpanID:        model.NewSpanID(uint64(dbSpan.SpanID)),
106			OperationName: dbSpan.OperationName,
107			//nolint:gosec // G115
108			References: model.MaybeAddParentSpanID(traceID, model.NewSpanID(uint64(dbSpan.ParentID)), refs),
109			//nolint:gosec // G115
110			Flags: model.Flags(uint32(dbSpan.Flags)),
111			//nolint:gosec // G115
112			StartTime: model.EpochMicrosecondsAsTime(uint64(dbSpan.StartTime)),
113			//nolint:gosec // G115
114			Duration: model.MicrosecondsAsDuration(uint64(dbSpan.Duration)),
115			Tags:     tags,
116			Warnings: warnings,
117			Logs:     logs,
118			Process:  process,
119		}
120		return span, nil
121	}
122	
123	func (c converter) fromDBTags(tags []KeyValue) ([]model.KeyValue, error) {
124		retMe := make([]model.KeyValue, 0, len(tags))
125		for i := range tags {
126			if strings.HasPrefix(tags[i].Key, warningStringPrefix) {
127				continue
128			}
129			kv, err := c.fromDBTag(&tags[i])
130			if err != nil {
131				return nil, err
132			}
133			retMe = append(retMe, kv)
134		}
135		return retMe, nil
136	}
137	
138	func (c converter) fromDBWarnings(tags []KeyValue) ([]string, error) {
139		var retMe []string
140		for _, tag := range tags {
141			if !strings.HasPrefix(tag.Key, warningStringPrefix) {
142				continue
143			}
144			kv, err := c.fromDBTag(&tag)
145			if err != nil {
146				return nil, err
147			}
148			retMe = append(retMe, kv.VStr)
149		}
150		return retMe, nil
151	}
152	
153	func (converter) fromDBTag(tag *KeyValue) (model.KeyValue, error) {
154		switch tag.ValueType {
155		case stringType:
156			return model.String(tag.Key, tag.ValueString), nil
157		case boolType:
158			return model.Bool(tag.Key, tag.ValueBool), nil
159		case int64Type:
160			return model.Int64(tag.Key, tag.ValueInt64), nil
161		case float64Type:
162			return model.Float64(tag.Key, tag.ValueFloat64), nil
163		case binaryType:
164			return model.Binary(tag.Key, tag.ValueBinary), nil
165		default:
166			return model.KeyValue{}, fmt.Errorf("invalid ValueType in %+v", tag)
167		}
168	}
169	
170	func (c converter) fromDBLogs(logs []Log) ([]model.Log, error) {
171		retMe := make([]model.Log, len(logs))
172		for i, l := range logs {
173			fields, err := c.fromDBTags(l.Fields)
174			if err != nil {
175				return nil, err
176			}
177			retMe[i] = model.Log{
178				//nolint:gosec // G115
179				Timestamp: model.EpochMicrosecondsAsTime(uint64(l.Timestamp)),
180				Fields:    fields,
181			}
182		}
183		return retMe, nil
184	}
185	
186	func (converter) fromDBRefs(refs []SpanRef) ([]model.SpanRef, error) {
187		retMe := make([]model.SpanRef, len(refs))
188		for i, r := range refs {
189			refType, ok := dbToDomainRefMap[r.RefType]
190			if !ok {
191				return nil, fmt.Errorf("invalid SpanRefType in %+v", r)
192			}
193			retMe[i] = model.SpanRef{
194				RefType: refType,
195				TraceID: r.TraceID.ToDomain(),
196				//nolint:gosec // G115
197				SpanID: model.NewSpanID(uint64(r.SpanID)),
198			}
199		}
200		return retMe, nil
201	}
202	
203	func (c converter) fromDBProcess(process Process) (*model.Process, error) {
204		tags, err := c.fromDBTags(process.Tags)
205		if err != nil {
206			return nil, err
207		}
208		return &model.Process{
209			Tags:        tags,
210			ServiceName: process.ServiceName,
211		}, nil
212	}
213	
214	func (converter) toDBTags(tags []model.KeyValue) []KeyValue {
215		retMe := make([]KeyValue, len(tags))
216		for i, t := range tags {
217			// do we want to validate a jaeger tag here? Making sure that the type and value matches up?
218			retMe[i] = KeyValue{
219				Key:          t.Key,
220				ValueType:    domainToDBValueTypeMap[t.VType],
221				ValueString:  t.VStr,
222				ValueBool:    t.Bool(),
223				ValueInt64:   t.Int64(),
224				ValueFloat64: t.Float64(),
225				ValueBinary:  t.Binary(),
226			}
227		}
228		return retMe
229	}
230	
231	func (converter) toDBWarnings(warnings []string) []KeyValue {
232		retMe := make([]KeyValue, len(warnings))
233		for i, w := range warnings {
234			kv := model.String(fmt.Sprintf("%s%d", warningStringPrefix, i+1), w)
235			retMe[i] = KeyValue{
236				Key:         kv.Key,
237				ValueType:   domainToDBValueTypeMap[kv.VType],
238				ValueString: kv.VStr,
239			}
240		}
241		return retMe
242	}
243	
244	func (c converter) toDBLogs(logs []model.Log) []Log {
245		retMe := make([]Log, len(logs))
246		for i, l := range logs {
247			retMe[i] = Log{
248				//nolint:gosec // G115
249				Timestamp: int64(model.TimeAsEpochMicroseconds(l.Timestamp)),
250				Fields:    c.toDBTags(l.Fields),
251			}
252		}
253		return retMe
254	}
255	
256	func (converter) toDBRefs(refs []model.SpanRef) []SpanRef {
257		retMe := make([]SpanRef, len(refs))
258		for i, r := range refs {
259			retMe[i] = SpanRef{
260				TraceID: TraceIDFromDomain(r.TraceID),
261				//nolint:gosec // G115
262				SpanID:  int64(r.SpanID),
263				RefType: domainToDBRefMap[r.RefType],
264			}
265		}
266		return retMe
267	}
