7	// GetAllUniqueTags creates a list of all unique tags from a set of filtered tags.
8	func GetAllUniqueTags(span *Span, tagFilter TagFilter) []TagInsertion {
9		allTags := append([]KeyValue{}, tagFilter.FilterProcessTags(span, span.Process.Tags)...)
10		allTags = append(allTags, tagFilter.FilterTags(span, span.Tags)...)
11		for _, log := range span.Logs {
12			allTags = append(allTags, tagFilter.FilterLogFields(span, log.Fields)...)
13		}
14		SortKVs(allTags)
15		uniqueTags := make([]TagInsertion, 0, len(allTags))
16		for i := range allTags {
17			if allTags[i].ValueType == binaryType {
18				continue // do not index binary tags
19			}
20			if i > 0 && allTags[i-1].Equal(&allTags[i]) {
21				continue // skip identical tags
22			}
23			uniqueTags = append(uniqueTags, TagInsertion{
24				ServiceName: span.Process.ServiceName,
25				TagKey:      allTags[i].Key,
26				TagValue:    allTags[i].AsString(),
27			})
28		}
29		return uniqueTags
