18	// V1BatchesFromTraces converts OpenTelemetry traces (ptrace.Traces)
19	// to Jaeger model batches ([]*model.Batch).
20	func V1BatchesFromTraces(traces ptrace.Traces) []*model.Batch {
21		batches := jaegertranslator.ProtoFromTraces(traces)
22		spanMap := createSpanMapFromBatches(batches)
23		transferWarningsToModelSpans(traces, spanMap)
24		return batches
25	}
26	
27	// V1BatchesToTraces converts Jaeger model batches ([]*model.Batch)
28	// to OpenTelemetry traces (ptrace.Traces).
29	func V1BatchesToTraces(batches []*model.Batch) ptrace.Traces {
30		traces, _ := jaegertranslator.ProtoToTraces(batches) // never returns an error
31		spanMap := jptrace.SpanMap(traces, func(s ptrace.Span) pcommon.SpanID {
32			return s.SpanID()
33		})
34		transferWarningsToOTLPSpans(batches, spanMap)
35		return traces
36	}
37	
38	// V1TracesFromSeq2 converts an interator of ptrace.Traces chunks into v1 traces.
39	func V1TracesFromSeq2(otelSeq iter.Seq2[[]ptrace.Traces, error]) ([]*model.Trace, error) {
40		var (
41			jaegerTraces []*model.Trace
42			iterErr      error
43		)
44		jptrace.AggregateTraces(otelSeq)(func(otelTrace ptrace.Traces, err error) bool {
45			if err != nil {
46				iterErr = err
47				return false
48			}
49			jaegerTraces = append(jaegerTraces, modelTraceFromOtelTrace(otelTrace))
50			return true
51		})
52		if iterErr != nil {
53			return nil, iterErr
54		}
55		return jaegerTraces, nil
56	}
57	
58	func V1TraceIDsFromSeq2(traceIDsIter iter.Seq2[[]tracestore.FoundTraceID, error]) ([]model.TraceID, error) {
59		var (
60			iterErr       error
61			modelTraceIDs []model.TraceID
62		)
63		traceIDsIter(func(traceIDs []tracestore.FoundTraceID, err error) bool {
64			if err != nil {
65				iterErr = err
66				return false
67			}
68			for _, traceID := range traceIDs {
69				modelTraceIDs = append(modelTraceIDs, ToV1TraceID(traceID.TraceID))
70			}
71			return true
72		})
73		if iterErr != nil {
74			return nil, iterErr
75		}
76		return modelTraceIDs, nil
77	}
78	
79	// V1TraceToOtelTrace converts v1 traces (*model.Trace) to Otel traces (ptrace.Traces)
80	func V1TraceToOtelTrace(jTrace *model.Trace) ptrace.Traces {
81		batches := createBatchesFromModelTrace(jTrace)
82		return V1BatchesToTraces(batches)
83	}
84	
85	func createBatchesFromModelTrace(jTrace *model.Trace) []*model.Batch {
86		spans := jTrace.Spans
87	
88		if len(spans) == 0 {
89			return nil
90		}
91		batch := &model.Batch{
92			Spans: jTrace.Spans,
93		}
94		return []*model.Batch{batch}
95	}
96	
97	// modelTraceFromOtelTrace extracts spans from otel traces
98	func modelTraceFromOtelTrace(otelTrace ptrace.Traces) *model.Trace {
99		var spans []*model.Span
100		batches := V1BatchesFromTraces(otelTrace)
101		for _, batch := range batches {
102			for _, span := range batch.Spans {
103				if span.Process == nil {
104					proc := *batch.Process // shallow clone
105					span.Process = &proc
106				}
107				spans = append(spans, span)
108	
109				if span.Process.Tags == nil {
110					span.Process.Tags = []model.KeyValue{}
111				}
112	
113				if span.References == nil {
114					span.References = []model.SpanRef{}
115				}
116				if span.Tags == nil {
117					span.Tags = []model.KeyValue{}
118				}
119			}
120		}
121		return &model.Trace{Spans: spans}
122	}
123	
124	func createSpanMapFromBatches(batches []*model.Batch) map[model.SpanID]*model.Span {
125		spanMap := make(map[model.SpanID]*model.Span)
126		for _, batch := range batches {
127			for _, span := range batch.Spans {
128				spanMap[span.SpanID] = span
129			}
130		}
131		return spanMap
132	}
133	
134	func transferWarningsToModelSpans(traces ptrace.Traces, spanMap map[model.SpanID]*model.Span) {
135		resources := traces.ResourceSpans()
136		for i := 0; i < resources.Len(); i++ {
137			scopes := resources.At(i).ScopeSpans()
138			for j := 0; j < scopes.Len(); j++ {
139				spans := scopes.At(j).Spans()
140				for k := 0; k < spans.Len(); k++ {
141					otelSpan := spans.At(k)
142					warnings := jptrace.GetWarnings(otelSpan)
143					if len(warnings) == 0 {
144						continue
145					}
146					if span, ok := spanMap[ToV1SpanID(otelSpan.SpanID())]; ok {
147						span.Warnings = append(span.Warnings, warnings...)
148						// filter out the warning tag
149						span.Tags = filterTags(span.Tags, jptrace.WarningsAttribute)
150					}
151				}
152			}
153		}
154	}
155	
156	func transferWarningsToOTLPSpans(batches []*model.Batch, spanMap map[pcommon.SpanID]ptrace.Span) {
157		for _, batch := range batches {
158			for _, span := range batch.Spans {
159				if len(span.Warnings) == 0 {
160					continue
161				}
162				if otelSpan, ok := spanMap[FromV1SpanID(span.SpanID)]; ok {
163					jptrace.AddWarnings(otelSpan, span.Warnings...)
164				}
165			}
166		}
167	}
168	
169	func filterTags(tags []model.KeyValue, keyToRemove string) []model.KeyValue {
170		var filteredTags []model.KeyValue
171		for _, tag := range tags {
172			if tag.Key != keyToRemove {
173				filteredTags = append(filteredTags, tag)
174			}
175		}
176		return filteredTags
177	}
