const (
	attributeExporterVersion = "opencensus.exporterversion"
)

var errType = errors.New("invalid type")

// FromDBModel converts a slice of Cassandra DB model spans into OTel traces.
func FromDBModel(spans []dbmodel.Span) ptrace.Traces {
	traceData := ptrace.NewTraces()
	if len(spans) == 0 {
		return traceData
	}
	dbSpansToSpans(spans, traceData.ResourceSpans())
	return traceData
}

// processGroup accumulates all DB spans that share the same process so that
// they can be emitted as a single ResourceSpans, matching the OTel data model
// where a process maps to a single Resource.
type processGroup struct {
	process dbmodel.Process
	spans   []dbmodel.Span
}

func dbSpansToSpans(spans []dbmodel.Span, rss ptrace.ResourceSpansSlice) {
	var groups []*processGroup
	index := make(map[string]*processGroup)

	for i := range spans {
		key := processKey(spans[i].Process)
		group, found := index[key]
		if !found {
			group = &processGroup{process: spans[i].Process}
			index[key] = group
			groups = append(groups, group)
		}
		group.spans = append(group.spans, spans[i])
	}

	rss.EnsureCapacity(len(groups))
	for _, group := range groups {
		rs := rss.AppendEmpty()
		dbProcessToResource(group.process, rs.Resource())
		dbSpansToScopeSpans(group.spans, rs.ScopeSpans())
	}
}

// processKey computes a stable string key that uniquely identifies a process
// by its service name and tags, used to group spans into ResourceSpans.
func processKey(process dbmodel.Process) string {
	var sb strings.Builder
	sb.WriteString(process.ServiceName)
	for _, tag := range process.Tags {
		sb.WriteByte(0)
		sb.WriteString(tag.Key)
		sb.WriteByte(0)
		sb.WriteString(tag.ValueType)
		sb.WriteByte(0)
		sb.WriteString(tag.AsString())
	}
	return sb.String()
}

func dbProcessToResource(process dbmodel.Process, dest pcommon.Resource) {
	if process.ServiceName == noServiceName {
		return
	}

	serviceName := process.ServiceName
	tags := process.Tags
	if serviceName == "" && tags == nil {
		return
	}

	attrs := dest.Attributes()
	if serviceName != "" {
		attrs.EnsureCapacity(len(tags) + 1)
		attrs.PutStr(otelsemconv.ServiceNameKey, serviceName)
	} else {
		attrs.EnsureCapacity(len(tags))
	}
	dbTagsToAttributes(tags, attrs)

	// Handle special keys translations.
	translateHostnameAttr(attrs)
	translateJaegerVersionAttr(attrs)
}

// translateHostnameAttr translates "hostname" atttribute
func translateHostnameAttr(attrs pcommon.Map) {
	hostname, hostnameFound := attrs.Get("hostname")
	_, convHostNameFound := attrs.Get(otelsemconv.HostNameKey)
	if hostnameFound && !convHostNameFound {
		hostname.CopyTo(attrs.PutEmpty(otelsemconv.HostNameKey))
		attrs.Remove("hostname")
	}
}

// translateHostnameAttr translates "jaeger.version" atttribute
func translateJaegerVersionAttr(attrs pcommon.Map) {
	jaegerVersion, jaegerVersionFound := attrs.Get("jaeger.version")
	_, exporterVersionFound := attrs.Get(attributeExporterVersion)
	if jaegerVersionFound && !exporterVersionFound {
		attrs.PutStr(attributeExporterVersion, "Jaeger-"+jaegerVersion.Str())
		attrs.Remove("jaeger.version")
	}
}

type scope struct {
	name, version string
}

func dbSpansToScopeSpans(spans []dbmodel.Span, dest ptrace.ScopeSpansSlice) {
	spansByLibrary := make(map[scope]ptrace.SpanSlice)

	for i := range spans {
		il := dbSpanScope(spans[i])
		sps, found := spansByLibrary[il]
		if !found {
			ss := dest.AppendEmpty()
			ss.Scope().SetName(il.name)
			ss.Scope().SetVersion(il.version)
			sps = ss.Spans()
			spansByLibrary[il] = sps
		}
		dbSpanToSpan(spans[i], sps.AppendEmpty())
	}
}

func dbSpanToSpan(span dbmodel.Span, dest ptrace.Span) {
	dest.SetTraceID(pcommon.TraceID(span.TraceID))
	dest.SetSpanID(idutils.UInt64ToSpanID(uint64(span.SpanID)))
	dest.SetName(span.OperationName)
	dest.SetStartTimestamp(microsecondsToTimestamp(span.StartTime))
	dest.SetEndTimestamp(microsecondsToTimestamp(span.StartTime + span.Duration))

	parentSpanID := dbSpanParentID(span)
	if parentSpanID != 0 {
		dest.SetParentSpanID(idutils.UInt64ToSpanID(uint64(parentSpanID)))
	}

	attrs := dest.Attributes()
	attrs.EnsureCapacity(len(span.Tags))
	dbTagsToAttributes(span.Tags, attrs)

	// The scope name/version tags were consumed to create the ScopeSpans, so
	// remove them from the span attributes.
	if _, ok := attrs.Get(otelsemconv.AttributeOtelScopeName); ok {
		attrs.Remove(otelsemconv.AttributeOtelScopeName)
		attrs.Remove(otelsemconv.AttributeOtelScopeVersion)
	}

	if spanKindAttr, ok := attrs.Get(model.SpanKindKey); ok {
		dest.SetKind(jSpanKindToInternal(spanKindAttr.Str()))
		attrs.Remove(model.SpanKindKey)
	}
	setSpanStatus(attrs, dest)

	dest.TraceState().FromRaw(getTraceStateFromAttrs(attrs))

	// drop the attributes slice if all of them were replaced during translation
	if attrs.Len() == 0 {
		attrs.Clear()
	}

	dbLogsToSpanEvents(span.Logs, dest.Events())
	dbReferencesToSpanLinks(span.Refs, parentSpanID, dest.Links())
}

// microsecondsToTimestamp converts epoch microseconds to a pcommon.Timestamp
// (nanoseconds since epoch).
func microsecondsToTimestamp(micros int64) pcommon.Timestamp {
	return pcommon.Timestamp(micros * 1000)
}

// dbSpanScope extracts the instrumentation scope encoded in the span tags.
func dbSpanScope(span dbmodel.Span) scope {
	il := scope{}
	if name, ok := getDBTag(span.Tags, otelsemconv.AttributeOtelScopeName); ok {
		il.name = name
		if version, ok := getDBTag(span.Tags, otelsemconv.AttributeOtelScopeVersion); ok {
			il.version = version
		}
	}
	return il
}

func getDBTag(tags []dbmodel.KeyValue, key string) (string, bool) {
	for i := range tags {
		if tags[i].Key == key {
			return tags[i].ValueString, true
		}
	}
	return "", false
}

