func main() {
	data, err := os.ReadFile(dir + "otel_traces_01.json")
	must(err)
	um := ptrace.JSONUnmarshaler{}
	m := ptrace.JSONMarshaler{}

	td, err := um.UnmarshalTraces(data)
	must(err)

	// Find a fixed point on the OTel side so that both directions round-trip.
	prev, err := m.MarshalTraces(td)
	must(err)
	var db []interface{ any }
	_ = db
	for i := 0; i < 10; i++ {
		spans := tracestore.ToDBModel(td)
		td2 := tracestore.FromDBModel(spans)
		cur, err := m.MarshalTraces(td2)
		must(err)
		if bytes.Equal(prev, cur) {
			fmt.Printf("fixed point reached at iteration %d\n", i)
			break
		}
		td = td2
		prev = cur
		if i == 9 {
			fmt.Println("WARNING: no fixed point after 10 iterations")
		}
	}

	// Now td is the fixed point.
	spans := tracestore.ToDBModel(td)

	// Verify round trip both ways.
	td3 := tracestore.FromDBModel(spans)
	a, err := m.MarshalTraces(td)
	must(err)
	b, err := m.MarshalTraces(td3)
	must(err)
	if !bytes.Equal(a, b) {
		fmt.Println("MISMATCH: FromDBModel(ToDBModel(td)) != td")
		os.WriteFile("/tmp/a.json", a, 0o644)
		os.WriteFile("/tmp/b.json", b, 0o644)
	} else {
		fmt.Println("OK: FromDBModel(ToDBModel(td)) == td")
	}

	// Write otel fixture (pretty).
	var pretty bytes.Buffer
	must(json.Indent(&pretty, a, "", "  "))
	must(os.WriteFile(dir+"otel_traces_01.json", pretty.Bytes(), 0o644))

	// Write cas fixture using encoder with 2-space indent (matches test style).
	buf := &bytes.Buffer{}
	enc := json.NewEncoder(buf)
	enc.SetIndent("", "  ")
	must(enc.Encode(spans))
	must(os.WriteFile(dir+"cas_01.json", buf.Bytes(), 0o644))

	fmt.Printf("wrote %d spans\n", len(spans))
	fmt.Println("=== cas_01.json ===")
	fmt.Println(buf.String())
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}
